package system

import (
	"net/url"
	"strings"
)

func oauthSecurityScheme(publicURL string) map[string]any {
	issuer := strings.TrimRight(publicURL, "/")
	return map[string]any{
		"type":        "oauth2",
		"description": "Authorization Code with mandatory PKCE S256. Access is bound to one API or MCP resource, one team, explicitly consented sites, scopes, and the user's current permissions. Dashboard administration does not accept OAuth tokens. Existing API-client credentials remain supported separately.",
		"flows": map[string]any{"authorizationCode": map[string]any{
			"authorizationUrl": issuer + "/oauth/authorize", "tokenUrl": issuer + "/oauth/token",
			"scopes": map[string]string{
				"sites:read": "Discover granted sites.", "analytics:read": "Read approved aggregate analytics.",
				"tracking_domains:read": "Discover eligible active tracking domains.", "ingest:write": "Submit server-side analytics for granted sites.",
			},
		}},
	}
}

func openAPIV1OAuthPaths(publicURL string) map[string]any {
	siteID := []any{paramRef("#/components/parameters/siteID")}
	paths := map[string]any{
		"/oauth/authorize": map[string]any{"get": op([]string{"OAuth"}, "Start authorization", "Public-client Authorization Code flow processed by Fosite. Requires client_id, exact redirect_uri, response_type=code, state, scope, resource, code_challenge, and code_challenge_method=S256. The resource is the canonical issuer URL plus /api or the enabled configured MCP mount. A validated request redirects to native login/setup and explicit consent; authentication never grants consent automatically. Public HTTPS Client ID Metadata Documents are validated with bounded SSRF protections. No implicit, password, client-credentials, dynamic registration, or identity-token flow.", nil, []any{
			map[string]any{"name": "client_id", "in": "query", "required": true, "schema": map[string]any{"type": "string"}},
			map[string]any{"name": "redirect_uri", "in": "query", "required": true, "schema": map[string]any{"type": "string", "format": "uri"}},
			map[string]any{"name": "response_type", "in": "query", "required": true, "schema": map[string]any{"const": "code"}},
			map[string]any{"name": "state", "in": "query", "required": true, "schema": map[string]any{"type": "string", "minLength": 8, "maxLength": 1024}},
			map[string]any{"name": "scope", "in": "query", "required": true, "schema": map[string]any{"type": "string"}},
			map[string]any{"name": "resource", "in": "query", "required": true, "schema": map[string]any{"type": "string", "format": "uri"}},
			map[string]any{"name": "code_challenge", "in": "query", "required": true, "schema": map[string]any{"type": "string", "minLength": 43, "maxLength": 43}},
			map[string]any{"name": "code_challenge_method", "in": "query", "required": true, "schema": map[string]any{"const": "S256"}},
		}, nil, map[string]any{"303": desc("Native consent or previously validated registered callback, preserving state and issuer."), "400": jsonRefResp("Invalid authorization request", "#/components/schemas/OAuthError"), "503": jsonRefResp("Authoritative node unavailable", "#/components/schemas/OAuthError")})},
		"/oauth/token": map[string]any{"post": op([]string{"OAuth"}, "Exchange code or rotate refresh token", "Public clients use token_endpoint_auth_method=none. Fosite verifies PKCE, client, exact redirect URI, resource binding, single use, and refresh rotation. Access tokens are short-lived opaque values. Refresh replay revokes the containing grant. Tokens are stored only as hashes. The same resource must be supplied on code exchange and refresh; scope cannot expand. Cross-origin requests are supported without browser credentials.", nil, nil,
			map[string]any{"required": true, "content": map[string]any{"application/x-www-form-urlencoded": map[string]any{"schema": map[string]any{
				"type": "object", "required": []string{"grant_type", "client_id", "resource"},
				"properties": map[string]any{"grant_type": map[string]any{"enum": []string{"authorization_code", "refresh_token"}}, "client_id": map[string]any{"type": "string"}, "resource": map[string]any{"type": "string", "format": "uri"}, "code": map[string]any{"type": "string"}, "code_verifier": map[string]any{"type": "string"}, "redirect_uri": map[string]any{"type": "string", "format": "uri"}, "refresh_token": map[string]any{"type": "string"}, "scope": map[string]any{"type": "string"}},
				"oneOf":      []any{map[string]any{"properties": map[string]any{"grant_type": map[string]any{"const": "authorization_code"}}, "required": []string{"code", "code_verifier", "redirect_uri"}}, map[string]any{"properties": map[string]any{"grant_type": map[string]any{"const": "refresh_token"}}, "required": []string{"refresh_token"}}},
			}}}}, map[string]any{"200": jsonRefResp("Opaque access token and rotating refresh token", "#/components/schemas/OAuthTokenResponse"), "400": jsonRefResp("Invalid or replayed grant", "#/components/schemas/OAuthError"), "503": jsonRefResp("Authoritative node unavailable", "#/components/schemas/OAuthError")})},
		"/oauth/revoke": map[string]any{"post": op([]string{"OAuth"}, "Revoke an integration credential", "Revokes the matching client-owned credential family. Unknown credentials return success without disclosure. Public clients do not send a client secret. Cross-origin requests are supported without browser credentials.", nil, nil,
			map[string]any{"required": true, "content": map[string]any{"application/x-www-form-urlencoded": map[string]any{"schema": map[string]any{"type": "object", "required": []string{"client_id", "token"}, "properties": map[string]any{"client_id": map[string]any{"type": "string"}, "token": map[string]any{"type": "string"}, "token_type_hint": map[string]any{"type": "string"}}}}}}, map[string]any{"200": desc("Revocation processed; empty body."), "400": jsonRefResp("Invalid revocation request", "#/components/schemas/OAuthError"), "503": jsonRefResp("Authoritative node unavailable", "#/components/schemas/OAuthError")})},
		"/api/oauth/continuation": map[string]any{"get": op([]string{"OAuth"}, "Check pending authorization", "Human session only. Validates the signed browser-bound pending request and expiry. Missing or invalid pending state returns false, including ordinary login when OAuth is unavailable. An authoritative validation outage returns a safe retriable error. No request handle, callback URI, or token is returned.", secCookie(), nil, nil, map[string]any{"200": jsonSchemaResp("Pending authorization", map[string]any{"type": "object", "required": []string{"pending"}, "properties": map[string]any{"pending": map[string]any{"type": "boolean"}}}), "401": errResp("Human session required"), "503": jsonRefResp("Validation unavailable", "#/components/schemas/OAuthError")})},
		"/api/oauth/consent": map[string]any{
			"get": op([]string{"OAuth"}, "Read consent choices", "Human session and browser-bound pending authorization only. Lists teams and sites currently eligible for all requested scopes. Returns only safe client display information and a user-bound CSRF token.", secCookie(), nil, nil, map[string]any{"200": jsonRefResp("Consent choices", "#/components/schemas/OAuthConsent"), "401": errResp("Human session required"), "410": jsonRefResp("Pending request expired", "#/components/schemas/OAuthError"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")}),
			"post": op([]string{"OAuth"}, "Approve or deny consent", "Native same-origin HTML form; human session, browser binding, and CSRF required. Approval selects exactly one team and at least one explicitly authorized site. All current permissions are rechecked before issuance. Success or denial redirects directly to the validated client callback with state and iss. Local failures redirect only to /oauth/consent?error=expired|forbidden|unavailable|failed. No authorization code passes through dashboard JavaScript.", secCookie(), nil,
				map[string]any{"required": true, "content": map[string]any{"application/x-www-form-urlencoded": map[string]any{"schema": map[string]any{"type": "object", "required": []string{"decision", "csrf_token"}, "properties": map[string]any{"decision": map[string]any{"enum": []string{"approve", "deny"}}, "team_id": map[string]any{"type": "string", "format": "uuid"}, "site_ids": map[string]any{"type": "array", "maxItems": 512, "items": map[string]any{"type": "string", "format": "uuid"}}, "csrf_token": map[string]any{"type": "string"}}}, "encoding": map[string]any{"site_ids": map[string]any{"style": "form", "explode": true}}}}}, map[string]any{"303": desc("Validated client callback or fixed local consent error page."), "401": errResp("Human session required")}),
		},
		"/api/user/oauth-grants":                        map[string]any{"get": op([]string{"OAuth"}, "List connected applications", "Human session only; lists the current user's grants and safe display metadata. Tokens and client secrets are never returned.", secCookie(), nil, nil, map[string]any{"200": jsonSchemaResp("Connected applications", map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/OAuthAuthorizedApp"}}), "401": errResp("Human session required"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")})},
		"/api/user/oauth-grants/{id}":                   map[string]any{"delete": op([]string{"OAuth"}, "Disconnect an application", "Human session and same-origin protection required. Only the grant owner can revoke it; revocation commits before success. Foreign and nonexistent grants are indistinguishable.", secCookie(), []any{map[string]any{"name": "id", "in": "path", "required": true, "schema": map[string]any{"type": "string", "format": "uuid"}}}, nil, map[string]any{"204": desc("Grant revoked."), "400": errResp("Invalid ID"), "401": errResp("Human session required"), "404": errResp("Grant not found"), "503": jsonRefResp("Unavailable", "#/components/schemas/OAuthError")})},
		"/api/integrations/sites":                       map[string]any{"get": op([]string{"Integrations"}, "Discover granted sites", "API-resource OAuth token only. Filters consented sites against the user's current authority in the grant's team, independently of the selected dashboard team.", []any{map[string]any{"oauth2": []string{"sites:read"}}}, nil, nil, map[string]any{"200": jsonSchemaResp("Granted sites", map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/IntegrationSite"}}), "401": jsonRefResp("Invalid token", "#/components/schemas/OAuthError"), "403": errResp("Insufficient scope or authority"), "503": errResp("Unavailable")})},
		"/api/integrations/sites/{id}/tracking-domains": map[string]any{"get": op([]string{"Integrations"}, "Discover eligible tracking domains", "API-resource OAuth token, explicit site consent, and current site.view authority required. Custom domains remain entitlement-gated and active-only. Returns no verification tokens, DNS, or TLS administration state. The canonical instance remains the endpoint for OAuth and server-side ingest.", []any{map[string]any{"oauth2": []string{"tracking_domains:read"}}}, siteID, nil, map[string]any{"200": jsonRefResp("Tracking endpoints", "#/components/schemas/IntegrationTrackingDomains"), "400": errResp("Invalid ID"), "401": errResp("Invalid token"), "403": errResp("Insufficient scope or authority"), "503": errResp("Unavailable")})},
		"/api/integrations/sites/{id}/preview":          map[string]any{"get": op([]string{"Integrations"}, "Read an aggregate analytics preview", "API-resource OAuth token, explicit site consent, and current site.view authority required. Fixed trailing seven days in UTC; query parameters are rejected. Uses the existing tenant analytics store and aggregate overview.", []any{map[string]any{"oauth2": []string{"analytics:read"}}}, siteID, nil, map[string]any{"200": jsonRefResp("Aggregate preview", "#/components/schemas/IntegrationPreview"), "400": errResp("Invalid ID or query"), "401": errResp("Invalid token"), "403": errResp("Insufficient scope or authority"), "503": errResp("Unavailable")})},
	}
	if issuer, err := url.Parse(publicURL); err == nil && issuer.Host != "" {
		prefix := strings.TrimRight(issuer.Path, "/")
		origin := issuer.Scheme + "://" + issuer.Host
		for _, path := range []string{"/.well-known/oauth-authorization-server" + prefix, "/.well-known/oauth-protected-resource" + prefix + "/api"} {
			paths[path] = map[string]any{"servers": []map[string]string{{"url": origin}}, "get": op([]string{"OAuth"}, "Read OAuth discovery metadata", "Canonical issuer and API protected-resource metadata, including path-prefixed deployments. MCP protected-resource metadata follows the configured enabled MCP resource. OAuth requires a compatible public HTTPS issuer.", nil, nil, nil, map[string]any{"200": jsonSchemaResp("Discovery metadata", map[string]any{"type": "object"})})}
		}
	}
	return paths
}

func openAPIV1OAuthSchemas() map[string]any {
	return map[string]any{
		"OAuthError":                 map[string]any{"type": "object", "required": []string{"error"}, "properties": map[string]any{"error": map[string]any{"type": "string"}}},
		"OAuthTokenResponse":         map[string]any{"type": "object", "required": []string{"access_token", "token_type", "expires_in", "refresh_token"}, "properties": map[string]any{"access_token": map[string]any{"type": "string"}, "token_type": map[string]any{"const": "bearer"}, "expires_in": map[string]any{"type": "integer"}, "refresh_token": map[string]any{"type": "string"}, "scope": map[string]any{"type": "string"}, "resource": map[string]any{"type": "string", "format": "uri"}}},
		"OAuthClient":                map[string]any{"type": "object", "required": []string{"id", "name"}, "properties": map[string]any{"id": map[string]any{"type": "string"}, "name": map[string]any{"type": "string"}, "callback_origin": map[string]any{"type": "string", "format": "uri"}}},
		"IntegrationSite":            map[string]any{"type": "object", "required": []string{"id", "domain"}, "properties": map[string]any{"id": map[string]any{"type": "string", "format": "uuid"}, "domain": map[string]any{"type": "string"}, "name": map[string]any{"type": "string"}}},
		"OAuthTeam":                  map[string]any{"type": "object", "required": []string{"id", "name"}, "properties": map[string]any{"id": map[string]any{"type": "string", "format": "uuid"}, "name": map[string]any{"type": "string"}, "sites": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/IntegrationSite"}}}},
		"OAuthConsent":               map[string]any{"type": "object", "required": []string{"client", "resource", "scopes", "expires_at", "csrf_token", "teams"}, "properties": map[string]any{"client": map[string]any{"$ref": "#/components/schemas/OAuthClient"}, "resource": map[string]any{"type": "string", "format": "uri"}, "scopes": map[string]any{"type": "array", "items": map[string]any{"type": "string"}}, "expires_at": map[string]any{"type": "string", "format": "date-time"}, "csrf_token": map[string]any{"type": "string"}, "teams": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/OAuthTeam"}}}},
		"OAuthAuthorizedApp":         map[string]any{"type": "object", "required": []string{"id", "client", "team", "sites", "scopes", "resource", "created_at", "expires_at"}, "properties": map[string]any{"id": map[string]any{"type": "string", "format": "uuid"}, "client": map[string]any{"$ref": "#/components/schemas/OAuthClient"}, "team": map[string]any{"$ref": "#/components/schemas/OAuthTeam"}, "sites": map[string]any{"type": "array", "items": map[string]any{"$ref": "#/components/schemas/IntegrationSite"}}, "scopes": map[string]any{"type": "array", "items": map[string]any{"type": "string"}}, "resource": map[string]any{"type": "string", "format": "uri"}, "created_at": map[string]any{"type": "string", "format": "date-time"}, "expires_at": map[string]any{"type": "string", "format": "date-time"}, "last_used_at": map[string]any{"type": "string", "format": "date-time"}}},
		"IntegrationTrackingDomains": map[string]any{"type": "object", "required": []string{"default_script_url", "active_custom_domains"}, "properties": map[string]any{"default_script_url": map[string]any{"type": "string", "format": "uri"}, "active_custom_domains": map[string]any{"type": "array", "items": map[string]any{"type": "object", "required": []string{"hostname", "script_url"}, "properties": map[string]any{"hostname": map[string]any{"type": "string"}, "script_url": map[string]any{"type": "string", "format": "uri"}}}}}},
		"IntegrationPreview":         map[string]any{"type": "object", "required": []string{"site_id", "start", "end", "total_pageviews", "unique_sessions", "bounce_rate"}, "properties": map[string]any{"site_id": map[string]any{"type": "string", "format": "uuid"}, "start": map[string]any{"type": "string", "format": "date-time"}, "end": map[string]any{"type": "string", "format": "date-time"}, "total_pageviews": map[string]any{"type": "integer"}, "unique_sessions": map[string]any{"type": "integer"}, "bounce_rate": map[string]any{"type": "number"}}},
	}
}
